from pathlib import Path

path = Path(__file__).resolve().parent / 'apply_associative_core_hardening.py'
text = path.read_text(encoding='utf-8')
old_block = """old = r'''           model: String(item.model || ''), model_key: String(item.model_key || item.model_family_key || ''), selected: Boolean(item.selected), association_score: finiteOrNull(item.association_score), final_score: finiteOrNull(item.final_score), analysisStatus: item.analysisStatus || null,\n'''\nnew = r'''           model: String(item.model || ''), model_label: String(item.model_label || item.model || ''), model_key: String(item.model_key || item.model_family_key || ''), parser_version: String(item.parser_version || item.morpheme_analysis?.parser_version || ''), morpheme_analysis: item.morpheme_analysis && typeof item.morpheme_analysis === 'object' ? {\n             parser_version: String(item.morpheme_analysis.parser_version || item.parser_version || ''), language: String(item.morpheme_analysis.language || ''), element_type: String(item.morpheme_analysis.element_type || ''), canonical_root: String(item.morpheme_analysis.canonical_root || ''), matched_root_variant: String(item.morpheme_analysis.matched_root_variant || ''), prefix_chain: Array.isArray(item.morpheme_analysis.prefix_chain) ? item.morpheme_analysis.prefix_chain.map(String) : [], first_meaningful_derivational_element: String(item.morpheme_analysis.first_meaningful_derivational_element || ''), first_lexical_root_after_preposition: String(item.morpheme_analysis.first_lexical_root_after_preposition || ''), model_key: String(item.morpheme_analysis.model_key || item.model_key || ''), model_label: String(item.morpheme_analysis.model_label || item.model_label || item.model || ''), analysis_confidence: String(item.morpheme_analysis.analysis_confidence || ''), diagnostic_reason: String(item.morpheme_analysis.diagnostic_reason || ''), warnings: Array.isArray(item.morpheme_analysis.warnings) ? item.morpheme_analysis.warnings.slice(0, 8).map(String) : []\n           } : null, selected: Boolean(item.selected), association_score: finiteOrNull(item.association_score), final_score: finiteOrNull(item.final_score), analysisStatus: item.analysisStatus || null,\n'''\ntext = replace_once(text, old, new, 'persist morpheme fields')\n"""
new_block = """old = r'''model: String(item.model || ''), model_key: String(item.model_key || item.model_family_key || ''), selected: Boolean(item.selected), association_score: finiteOrNull(item.association_score), final_score: finiteOrNull(item.final_score), analysisStatus: item.analysisStatus || null,'''
new = r'''model: String(item.model || ''), model_label: String(item.model_label || item.model || ''), model_key: String(item.model_key || item.model_family_key || ''), parser_version: String(item.parser_version || item.morpheme_analysis?.parser_version || ''), morpheme_analysis: item.morpheme_analysis && typeof item.morpheme_analysis === 'object' ? {
             parser_version: String(item.morpheme_analysis.parser_version || item.parser_version || ''), language: String(item.morpheme_analysis.language || ''), element_type: String(item.morpheme_analysis.element_type || ''), canonical_root: String(item.morpheme_analysis.canonical_root || ''), matched_root_variant: String(item.morpheme_analysis.matched_root_variant || ''), prefix_chain: Array.isArray(item.morpheme_analysis.prefix_chain) ? item.morpheme_analysis.prefix_chain.map(String) : [], first_meaningful_derivational_element: String(item.morpheme_analysis.first_meaningful_derivational_element || ''), first_lexical_root_after_preposition: String(item.morpheme_analysis.first_lexical_root_after_preposition || ''), model_key: String(item.morpheme_analysis.model_key || item.model_key || ''), model_label: String(item.morpheme_analysis.model_label || item.model_label || item.model || ''), analysis_confidence: String(item.morpheme_analysis.analysis_confidence || ''), diagnostic_reason: String(item.morpheme_analysis.diagnostic_reason || ''), warnings: Array.isArray(item.morpheme_analysis.warnings) ? item.morpheme_analysis.warnings.slice(0, 8).map(String) : []
           } : null, selected: Boolean(item.selected), association_score: finiteOrNull(item.association_score), final_score: finiteOrNull(item.final_score), analysisStatus: item.analysisStatus || null,'''
text = replace_once(text, old, new, 'persist morpheme fields')
"""
if old_block not in text:
    raise SystemExit('repair target not found')
path.write_text(text.replace(old_block, new_block, 1), encoding='utf-8')
print('Repaired core patch matcher.')
